import{_ as n,l,o as e,c as i,v as t,p as s,x as r,d,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const k=JSON.parse('{"title":"线性时间排序","description":"","frontmatter":{"title":"线性时间排序","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/linear-time-sort.md","filePath":"cs/linear-time-sort.md","lastUpdated":1789023840000}'),c={name:"cs/linear-time-sort.md"};function E(_,a,m,T,u,A){const o=l("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="线性时间排序" tabindex="-1">线性时间排序 <a class="header-anchor" href="#线性时间排序" aria-label="Permalink to &quot;线性时间排序&quot;">​</a></h1><div class="epigraph"><p>当键是有界整数或固定长数字串，排序可以变成计数与按位分配，而不再问两两谁更大。</p><footer>—— 据 Knuth, TAOCP vol. 3；CLRS 第 8 章整理</footer></div><p>上一课<a href="/cs/sort-lower-bound">下界 Ω(n log n)</a>把比较模型钉死。本课不重画决策树。缺口是：键若是 \\(\\{0,\\ldots,k\\}\\) 上的整数，或 \\(d\\) 位 \\(r\\) 进制数字，信息不必来自比较。本课只交出计数排序与基数排序，说明 \\(O(n)\\) 何时合法。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>比较墙假设唯一的问题答案是「谁更小」。若键本身可当作数组下标，则一次扫描可以计入 \\(C[A[i]]\\)，前缀和给出秩，再稳定写回。代价 \\(\\Theta(n+k)\\)。当 \\(k=O(n)\\)，这是线性。缺口不是推翻下界，而是<strong>换模型</strong>：算法读的是键的数值，不是比较谓词。</p><p>基数排序对每一位做稳定的计数（或桶），从低位到高位（LSD）。\\(d\\) 位、每位点 \\(r\\) 种，总时间 \\(\\Theta(d(n+r))\\)。\\(d\\) 为常数、\\(r=O(n)\\) 时仍线性。</p><h3 id="计数不是散列" tabindex="-1">计数不是散列 <a class="header-anchor" href="#计数不是散列" aria-label="Permalink to &quot;计数不是散列&quot;">​</a></h3><p>散列把键打散到桶里但不保序；计数用键值当秩的原材料，前缀和是顺序。桶排序假设键来自均匀分布，期望线性，最坏仍可坏。本课主干是计数与 LSD 基数，不把桶排序的概率模型写完。</p><p><span class="marginnote">稳定是基数正确性的零件：低位排完后，高位相等的对必须保持低位次序。插入与归并可稳；堆排默认不稳，不能直接当基数的子过程。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>计数：开 \\(k+1\\) 个计数器，扫 \\(A\\) 填 \\(C\\)，前缀和，\\(A\\) 从右往左写入 \\(B\\)（保证稳定）。基数：对 \\(j=1..d\\) 用稳定计数按第 \\(j\\) 位排。正确性：归纳为「最低 \\(j\\) 位已有序」。</p>',11)),(e(),s(p,null,{default:r(()=>[h(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20KEY%5B%22%E6%95%B4%E6%95%B0%E9%94%AE%22%5D%20--%3E%20CNT%5B%22%E8%AE%A1%E6%95%B0%20%2B%20%E5%89%8D%E7%BC%80%E5%92%8C%22%5D%0A%20%20CNT%20--%3E%20ST%5B%22%E7%A8%B3%E5%AE%9A%E5%86%99%E5%9B%9E%22%5D%0A%20%20ST%20--%3E%20RAD%5B%22%E6%8C%89%E4%BD%8D%E9%87%8D%E5%A4%8D%20%E2%86%92%20%E5%9F%BA%E6%95%B0%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>空间 \\(\\Theta(n+k)\\)。与堆排就地对照：线性时间买的是值域数组。键为任意可比较对象时，退回比较排序。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>\\(k=\\omega(n)\\) 时计数不再线性，墙在比较模型外用空间说话。单词长 \\(w\\) 的 RAM 上，整数排序可以更快，那是更细的模型，本课不启用。也不把浮点当整数：IEEE 位型要先映射成可比较的无符号，组成课已有浮点，本课不重做。</p><p>后课选择第 \\(k\\) 小仍可在比较模型里线性；那是选，不是排完。本课的线性是<strong>全排序</strong>在受限键上。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不声称「排序是 \\(O(n)\\)」。没有值域假设，比较下界仍在。也不处理外存多路归并：那是块 I/O，不是计数。字符串按字典序的 MSD 基数与递归桶是另一条实现，主干留在 LSD。</p><p>后课默认：比较排序 \\(\\Omega(n\\log n)\\)；整数或定长数字串可用计数/基数到 \\(\\Theta(n+k)\\) 或 \\(\\Theta(d(n+r))\\)。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>离开比较模型后，计数给出 \\(\\Theta(n+k)\\)，基数按位稳定重复。</li><li>稳定是基数的前提；堆排不能直接代入。</li><li>\\(k\\) 太大则线性消失。</li><li>出处：Knuth, TAOCP vol. 3；CLRS 第 8 章。</li></ul>',9))])}const S=n(c,[["render",E]]);export{k as __pageData,S as default};
